/// Compare the actual song ModsGroup operations independently of player updates.
pub fn expose_legacy_song_option_operations(lua: &mlua::Lua) -> mlua::Result<()> {
    use crate::lua_util::method_arg;
    let operations = lua.create_table()?;
    for name in [
        "Select",
        "Text",
        "Assign",
        "Apply",
        "Restart",
        "ClearAttacks",
        "Advance",
    ] {
        let levels = lua
            .app_data_ref::<crate::song_tables::SongLuaOptionLevels>()
            .expect("installed game state")
            .songs
            .clone();
        operations.set(
            name,
            lua.create_function(move |lua, args: mlua::MultiValue| {
                match name {
                    "Restart" => crate::song_tables::restart_stage_options(lua)?,
                    "ClearAttacks" => crate::song_tables::clear_active_attack_options(lua)?,
                    "Advance" => {
                        let delta = lua.unpack::<f32>(
                            method_arg(&args, 0).cloned().unwrap_or(mlua::Value::Nil),
                        )?;
                        crate::song_tables::advance_option_levels_with_frame_delta(
                            lua, 0.0, delta,
                        )?;
                    }
                    _ => {
                        let level = crate::song_tables::options_level(method_arg(&args, 0))?;
                        match name {
                            "Select" => {
                                return Ok(mlua::MultiValue::from_vec(vec![mlua::Value::Table(
                                    levels[level].clone(),
                                )]));
                            }
                            "Text" => {
                                return Ok(mlua::MultiValue::from_vec(vec![mlua::Value::String(
                                    lua.create_string(crate::song_tables::song_options_text(
                                        &levels[level],
                                    )?)?,
                                )]));
                            }
                            _ => {
                                let text = method_arg(&args, 1)
                                    .cloned()
                                    .and_then(crate::read_string)
                                    .ok_or_else(|| {
                                        mlua::Error::runtime("Expected song options string")
                                    })?;
                                if name == "Assign" {
                                    crate::song_tables::assign_song_options(
                                        lua, &levels, level, &text,
                                    )?;
                                } else {
                                    for owner in &levels[level..] {
                                        crate::song_tables::migration_apply_song_options(
                                            owner, &text,
                                        )?;
                                    }
                                }
                            }
                        }
                    }
                }
                Ok(mlua::MultiValue::new())
            })?,
        )?;
    }
    let catalog: mlua::Table = lua.globals().get("catalog")?;
    catalog.raw_set("song_option_operations", operations)
}

